{"files":[{"path":"src/occupationalInfo/date.mjs","content":"export function validateSurveyDate(value, today) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return '日期格式错误';

  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return '无效日期';
  }

  if (value > today) return '调查日期不能晚于今日';

  return '';
}
"}]}
